pub type Nat = i2r_numeric::Nat;

pub fn zero_nat() -> Nat {
    Nat::zero()
}

pub fn suc(n: Nat) -> Nat {
    n + Nat::one()
}

pub fn plus_nat(a: &Nat, b: Nat) -> Nat {
    a + b
}

/// Private helper carrying the original source recurrence unchanged:
///   multip 0 n = 0
///   multip (Suc m) n = plus_nat n (multip m n)
/// The positive branch derives the predecessor of the positive `m` and
/// recurses on that predecessor, adding the untouched other factor.
fn multip_impl(m: &Nat, n: &Nat) -> Nat {
    if m.is_zero() {
        zero_nat()
    } else {
        let pred = m.sub_trunc(&Nat::one());
        plus_nat(n, multip_impl(&pred, n))
    }
}

/// Entry of the current extracted graph:
///   i2r_entry_0 = (\<lambda>m n. if m \<le> n then multip m n else multip n m)
/// The branch test is the exact source Nat less-than-or-equal primitive and only
/// the selected branch is evaluated; each branch delegates to the unchanged helper.
pub fn multip(m: &Nat, n: &Nat) -> Nat {
    if m <= n {
        multip_impl(m, n)
    } else {
        multip_impl(n, m)
    }
}

