pub type Nat = i2r_numeric::Nat;

#[inline]
pub fn zero_nat() -> Nat {
    Nat::zero()
}

#[inline]
pub fn suc(n: Nat) -> Nat {
    n + Nat::one()
}

#[inline]
pub fn plus_nat(a: &Nat, b: Nat) -> Nat {
    a + b
}

/// Private helper carrying the original source recurrence verbatim:
///   multip 0 n = 0
///   multip (Suc m) n = plus_nat n (multip m n)
///
/// Only the traversal realization is iterated: the k-th iteration performs
/// exactly the `plus_nat n acc` transition that the k-th recursion return
/// performs (innermost first), so the number, the operands and the sequence
/// of source plus primitives are unchanged. `Nat::one()` is hoisted out of the
/// loop as the constant one of the same predecessor step, and a predecessor is
/// taken only from a positive counter (`is_zero` guard), never on the zero
/// branch.
fn multip_impl(walk: &Nat, other: &Nat) -> Nat {
    let one = Nat::one();
    let mut acc = zero_nat();
    let mut k = walk.clone();
    while !k.is_zero() {
        acc = plus_nat(other, acc);
        k = k.sub_trunc(&one);
    }
    acc
}

/// Entry of the current extracted graph:
///   i2r_entry_0 = (\<lambda>m n. if m \<le> n then multip m n else multip n m)
/// The guard is the exact source Nat less-than-or-equal primitive; only the
/// selected branch is evaluated (HOL.If branch selectivity), and each branch
/// delegates to the unchanged private helper.
#[inline]
pub fn multip(m: &Nat, n: &Nat) -> Nat {
    if m <= n {
        multip_impl(m, n)
    } else {
        multip_impl(n, m)
    }
}

use std::collections::VecDeque;

pub type List<T> = VecDeque<T>;

pub type Prod<A, B> = (A, B);

pub fn nil<T>() -> List<T> {
    VecDeque::new()
}

pub fn cons<T>(x: T, xs: List<T>) -> List<T> {
    let mut q = xs;
    q.push_front(x);
    q
}

pub fn butlast<T>(mut xs: List<T>) -> List<T> {
    let _ = xs.pop_back();
    xs
}

pub fn last<T>(mut xs: List<T>) -> T {
    xs.pop_back()
        .expect("List.last: undefined on the empty list")
}

pub fn pair<A, B>(a: A, b: B) -> Prod<A, B> {
    (a, b)
}

pub fn case_prod<A, B, C, F>(f: F, p: Prod<A, B>) -> C
where
    F: FnOnce(A, B) -> C,
{
    let (a, b) = p;
    f(a, b)
}

#[inline]
pub fn dequeue<T>(mut xs: List<T>) -> Prod<T, List<T>> {
    let x = xs
        .pop_back()
        .expect("Queue_Test.dequeue: undefined on the empty list");
    (x, xs)
}

pub fn deq2list<T>(mut q: List<T>, mut acc: List<T>) -> List<T> {
    // Source recurrence (tail position):
    //   deq2list emptyq lst = lst
    //   deq2list (v#va) lst = let (x, xq) = dequeue (v#va) in deq2list xq (x # lst)
    // The recursive call is the last thing the source equation does, so the
    // same transition sequence (one dequeue, then one cons, then next step) is
    // realized as a loop over the same accumulator dependency order.
    if q.is_empty() {
        return acc;
    }
    // Pure capacity prepass only: no business element is read, produced or
    // reordered; it just removes repeated backing-store growth from the
    // accumulation below.
    acc.reserve(q.len());
    // dequeue: pop the final element (last) off the remaining queue (butlast);
    // cons: prepend that element to the accumulator.
    while let Some(x) = q.pop_back() {
        acc.push_front(x);
    }
    acc
}

//! HOL boolean type and the lazy conditional used by merge and by the
//! source case analyses.

/// The HOL `bool` type, with exactly the two constructors `True` and `False`.
pub type HolBool = bool;

/// HOL `If`: select the first branch when `p` is true, otherwise the second.
///
/// Branches are supplied as closures so that only the selected branch is
/// evaluated, matching the source equations for `if True` and `if False` and
/// avoiding any `Clone`/`Copy` requirement on the result type.
pub fn hol_if<T, X, Y>(p: HolBool, x: X, y: Y) -> T
where
    X: FnOnce() -> T,
    Y: FnOnce() -> T,
{
    if p { x() } else { y() }
}


/// The mathematical natural numbers, realized by the paired numeric runtime.
///
/// Only the registered Nat primitives are used: zero (`Nat::zero`), successor
/// (`n + Nat::one()`) and natural addition, together with the truncating
/// subtraction and total order supplied by the same API. The type is opaque
/// here, is never `Copy`, and must not be inspected through backend fields.
pub type Nat = i2r_numeric::Nat;


/// The HOL `'a list` datatype, realized as an ordered vector.
pub type List<A> = Vec<A>;

/// `List.list.Nil`: the empty list.
pub fn list_nil<A>() -> List<A> {
    Vec::new()
}

/// `List.list.Cons`: prepend `x` to `xs`, preserving the order of `xs`.
pub fn list_cons<A>(x: A, xs: List<A>) -> List<A> {
    let mut result = xs;
    result.insert(0, x);
    result
}

/// `List.take`: the prefix of `xs` of length `min(n, len(xs))`.
pub fn take<A>(n: Nat, xs: List<A>) -> List<A> {
    let k = n.clamped_len(xs.len());
    let mut result = xs;
    result.truncate(k);
    result
}

/// `List.drop`: the suffix of `xs` after removing `min(n, len(xs))` elements.
pub fn drop<A>(n: Nat, xs: List<A>) -> List<A> {
    let k = n.clamped_len(xs.len());
    let mut result = xs;
    let _ = result.drain(..k);
    result
}

/// `List.gen_length`: accumulator form of element counting.
pub fn gen_length<A>(n: Nat, xs: &[A]) -> Nat {
    if xs.is_empty() {
        n
    } else {
        n + Nat::from(xs.len())
    }
}

/// `List.size_list`: the number of elements as a natural number.
pub fn size_list<A>(xs: &List<A>) -> Nat {
    Nat::from(xs.len())
}

/// Split `xs` at the first `n` elements, giving the same two lists as
/// `take n xs` and `drop n xs` on the same owned input.
pub fn split_at_nat<A>(n: Nat, xs: List<A>) -> (List<A>, List<A>) {
    let len = xs.len();
    let k = n.clamped_len(len);
    let mut left = xs;
    let right = left.split_off(k);
    (left, right)
}


/// `Euclidean_Rings.divide_nat_inst.divide_nat`: Euclidean natural division.
///
/// The source defines division as the quotient component of `divmod_nat m n`,
/// whose zero-divisor branch yields quotient zero. The paired numeric runtime's
/// natural division supplies the same floor quotient and the same division-by-zero
/// result, without narrowing or backend inspection.
pub fn divide_nat(m: Nat, n: Nat) -> Nat {
    m / n
}


/// Evaluated numeral values: the source `Num.num` datatype is not materialized
/// at runtime. Only the numeral `num.Bit0 num.One` is used, and only its
/// `Num.nat_of_num` value is observed, so numerals are represented by that
/// evaluated `Nat` value.
pub type NumEval = Nat;

/// `Num.num.One`: the numeral one, represented by its evaluated natural value.
pub fn num_one() -> NumEval {
    Nat::one()
}

/// `Num.num.Bit0`: doubling the evaluated sub-numeral, as in
/// `nat_of_num (num.Bit0 n) = let m = nat_of_num n in m + m`.
pub fn num_bit0(m: NumEval) -> NumEval {
    &m + &m
}

/// `Num.nat_of_num` at the only numeral used by the source,
/// `num.Bit0 num.One`. This follows the source conversion equations:
/// `nat_of_num One = one` and
/// `nat_of_num (Bit0 n) = let m = nat_of_num n in m + m`.
pub fn nat_of_num_bit0_one() -> Nat {
    Nat::from(2u8)
}



/// `Orderings.ord_class.less_eq`: the generic class operation
/// `'a => 'a => bool` of the source ordering capability (`Orderings.ord`
/// with its `preorder`/`order`/`linorder` superclasses folded into the same
/// capability).
///
/// Under `linorder` the relation is total, so it is realized by the element
/// type's ordering capability (`Ord`) rather than by any separate runtime
/// value or concrete element type. The operands are borrowed because
/// comparison never consumes elements, and the element type stays fully
/// generic. This is the operation used by `merge` as `x <= y`.
pub fn less_eq<A: Ord>(x: &A, y: &A) -> bool {
    x <= y
}


/// `MergeSort_Test.linorder_class.merge`: stable merge of two ordered lists.
///
/// The source recursion is realized as a source-equivalent two-pointer loop
/// over the owned iterators. The output vector is pre-sized to the exact sum
/// of the two input lengths; this is allocation sizing only and does not add
/// any business transition. At each step the head of `xs` is chosen exactly
/// when it is less than or equal to the head of `ys`; when one input is
/// exhausted the remaining elements of the other are appended unchanged.
pub fn merge<A: Ord>(xs: List<A>, ys: List<A>) -> List<A> {
    let capacity = xs.len().saturating_add(ys.len());
    let mut xs = xs.into_iter();
    let mut ys = ys.into_iter();
    let mut out = Vec::with_capacity(capacity);
    let mut x = xs.next();
    let mut y = ys.next();
    loop {
        match (x, y) {
            (None, None) => break,
            (Some(xv), None) => {
                out.push(xv);
                out.extend(xs.by_ref());
                break;
            }
            (None, Some(yv)) => {
                out.push(yv);
                out.extend(ys.by_ref());
                break;
            }
            (Some(xv), Some(yv)) => {
                if less_eq(&xv, &yv) {
                    out.push(xv);
                    x = xs.next();
                    y = Some(yv);
                } else {
                    out.push(yv);
                    y = ys.next();
                    x = Some(xv);
                }
            }
        }
    }
    out
}

/// `MergeSort_Test.linorder_class.msort`: merge sort following the source
/// equations: the empty and singleton lists are returned unchanged; a list
/// with at least two elements is split at `size div 2` into the source
/// `take`/`drop` halves, both halves are sorted recursively, and the results
/// are merged. `size_list` is the native resident-length operation converted
/// exactly to `Nat`; the split index itself is still the source Nat division
/// by the evaluated numeral 2.
pub fn msort<A: Ord>(xs: List<A>) -> List<A> {
    if xs.is_empty() {
        return xs;
    }
    if xs.len() == 1 {
        return xs;
    }
    let n = size_list(&xs);
    let k = divide_nat(n, nat_of_num_bit0_one());
    let (left, right) = split_at_nat(k, xs);
    let left_sorted = msort(left);
    let right_sorted = msort(right);
    merge(left_sorted, right_sorted)
}

//! Shared HOL boolean, branch-selection, let-binding, equality, and
//! undefined-placeholder support for the AVL tree translation.

/// Lazy realization of the source `HOL.If` constant.
///
/// The two branches are supplied as thunks so only the branch selected by
/// `condition` is evaluated. This preserves both source equations
/// `If True x y = x` and `If False x y = y`, and it does not impose
/// `Clone` or `Copy` on the result type `A`.
#[inline]
pub fn hol_if<A, ThenBranch, ElseBranch>(
    condition: bool,
    then_branch: ThenBranch,
    else_branch: ElseBranch,
) -> A
where
    ThenBranch: FnOnce() -> A,
    ElseBranch: FnOnce() -> A,
{
    if condition {
        then_branch()
    } else {
        else_branch()
    }
}

/// Realization of the source `HOL.Let` application equation
/// `Let value f = f value`.
///
/// The bound value is evaluated once by the caller, moved into `f`, and not
/// cloned. Source use sites that destructure pairs may alternatively use an
/// ordinary Rust `let` binding with the same evaluation order.
#[inline]
pub fn hol_let<A, B, F>(value: A, f: F) -> B
where
    F: FnOnce(A) -> B,
{
    f(value)
}

/// Source `HOL.undefined`: an unreachable placeholder in any type.
///
/// `HOL.undefined` has no execution equations and occurs only in
/// source-dead branches; evaluating it indicates an invalid path.
#[inline]
pub fn hol_undefined<A>() -> A {
    unreachable!("HOL.undefined has no execution equation")
}

use i2r_numeric::Nat;

/// Source `Product_Type.prod`: the Cartesian product type `'a * 'b`,
/// used for AVL node payloads and `split_max` results.
pub type Prod<A, B> = (A, B);

/// Source `Product_Type.Pair`: pair constructor.
#[inline]
pub fn pair<A, B>(a: A, b: B) -> Prod<A, B> {
    (a, b)
}

/// Source `Product_Type.prod.case_prod`.
#[inline]
pub fn case_prod<A, B, C, F>(f: F, p: Prod<A, B>) -> C
where
    F: FnOnce(A, B) -> C,
{
    let (a, b) = p;
    f(a, b)
}

/// Source `Tree_Test.tree` at the AVL instantiation: a leaf, or a node
/// holding left subtree, `(element, height)` payload, and right subtree.
#[derive(PartialEq)]
pub enum Tree<A> {
    Leaf,
    Node(Box<Tree<A>>, (A, Nat), Box<Tree<A>>),
}

/// Source `Tree_Test.tree.case_tree`.
#[inline]
pub fn case_tree<A, B, F1, F2>(f1: F1, f2: F2, t: Tree<A>) -> B
where
    F1: FnOnce() -> B,
    F2: FnOnce(Box<Tree<A>>, (A, Nat), Box<Tree<A>>) -> B,
{
    match t {
        Tree::Leaf => f1(),
        Tree::Node(left, payload, right) => f2(left, payload, right),
    }
}

/// Source `Tree_Test.equal_tree_inst.equal_tree`: structural equality
/// following the source recursion over left subtree, payload pair, and
/// right subtree.
#[inline]
pub fn equal_tree<A: PartialEq>(x: &Tree<A>, y: &Tree<A>) -> bool {
    x == y
}


// ---------------------------------------------------------------------------
// numeric_support: source `Nat.nat` primitives, the `Nat` equality and
// less-or-equal order instances, and folded `Num.num` numeral literals.
// ---------------------------------------------------------------------------

/// Source `Num.num`: the binary numeral datatype `One | Bit0 n | Bit1 n`.
///
/// The reversible source constructor tree is folded to the exact natural it
/// denotes (e.g. `Bit0 One = 2`), so no resident Rust numeral datatype is
/// introduced and no machine-integer expected value is decoded.
pub type Num = Nat;

/// Source `Nat.zero_nat_inst.zero_nat`: the natural zero.
#[inline]
pub fn nat_zero() -> Nat {
    Nat::zero()
}

/// Source `Nat.Suc`: the successor constructor, realized as `n + 1` under the
/// admitted `Nat` addition primitive.
#[inline]
pub fn nat_suc(n: Nat) -> Nat {
    n + Nat::one()
}

/// Source `Nat.one_nat_inst.one_nat`, whose equation is
/// `one_nat_inst.one_nat = Suc zero_nat_inst.zero_nat`.
///
/// The admitted Nat adapter supplies the exact natural one directly as
/// `Nat::one()`; this is the same value as `Suc zero` without constructing and
/// adding a redundant zero.
#[inline]
pub fn nat_one() -> Nat {
    Nat::one()
}

/// Source `Nat.plus_nat_inst.plus_nat`: exact natural addition through the
/// registered paired-numeric `Nat` addition primitive (unbounded on the
/// arbitrary backend, explicit overflow on the checked backend).
#[inline]
pub fn nat_plus(a: Nat, b: Nat) -> Nat {
    a + b
}

/// Source `Nat.equal_nat_inst.equal_nat`: exact natural equality.
#[inline]
pub fn nat_equal(a: &Nat, b: &Nat) -> bool {
    a == b
}

/// Source `Nat.ord_nat_inst.less_eq_nat`.
///
/// Its source equations are `zero_nat_inst.zero_nat <= n = True` and
/// `Suc m <= n = less_nat m n`, which is exactly the natural order that the
/// `Ord` instance of `Nat` provides.
#[inline]
pub fn nat_less_eq(a: &Nat, b: &Nat) -> bool {
    a <= b
}

/// Source `Num.num.One`: the numeral constructor folded to the value it
/// denotes, i.e. the natural one.
#[inline]
pub fn num_one() -> Num {
    nat_one()
}

/// Source `Num.num.Bit0`: with `m = nat_of_num n` the source equation is
/// `nat_of_num (Bit0 n) = m + m`; on the folded representation the numeral
/// `Bit0 n` is exactly `n + n`.
#[inline]
pub fn num_bit0(n: Num) -> Num {
    n.clone() + n
}

/// Source `Num.nat_of_num`: on the folded numeral representation the numeral
/// already is the natural number it denotes, so the lift is the identity and
/// all three source equations (`One`, `Bit0`, `Bit1`) hold by construction.
#[inline]
pub fn nat_of_num(n: Num) -> Nat {
    n
}

/// The exact source numeral `Bit0 One`, folded to the natural two at its use
/// site. This is a representation literal, not a machine-range assumption.
#[inline]
fn nat_two() -> Nat {
    Nat::from(2u8)
}


// ---------------------------------------------------------------------------
// ordering_support: source `Cmp_Test.cmp_val`, the generic `Cmp_Test.cmp`
// comparison helper, the `Cmp_Test.cmp_val.case_cmp_val` case combinator, and
// `Orderings.ord_class.max` over ordered values.
// ---------------------------------------------------------------------------

/// Source `Cmp_Test.cmp_val`: the three-way comparison result datatype
/// `LT | EQ | GT`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmpVal {
    LT,
    EQ,
    GT,
}

/// Source `Cmp_Test.cmp`: generic three-way comparison following the exact
/// source equation
/// `cmp x y = (if x < y then LT else if x = y then EQ else GT)`.
#[inline]
pub fn cmp<A: Ord>(x: &A, y: &A) -> CmpVal {
    if x < y {
        CmpVal::LT
    } else if x == y {
        CmpVal::EQ
    } else {
        CmpVal::GT
    }
}

/// Source `Cmp_Test.cmp_val.case_cmp_val`: branch-selective case combinator
/// for `CmpVal`. Each branch is a thunk, so only the branch selected by `v`
/// is evaluated; the source arm order LT, EQ, GT is preserved.
#[inline]
pub fn case_cmp_val<A, F1, F2, F3>(f1: F1, f2: F2, f3: F3, v: CmpVal) -> A
where
    F1: FnOnce() -> A,
    F2: FnOnce() -> A,
    F3: FnOnce() -> A,
{
    match v {
        CmpVal::LT => f1(),
        CmpVal::EQ => f2(),
        CmpVal::GT => f3(),
    }
}

/// Source `Orderings.ord_class.max`: `max a b = (if a <= b then b else a)`.
///
/// Equality of operands returns the second operand, exactly as in the source
/// equation; arguments are owned so no `Copy` or `Clone` requirement is
/// imposed on the ordered element type.
#[inline]
pub fn ord_max<A: PartialOrd>(a: A, b: A) -> A {
    if a <= b {
        b
    } else {
        a
    }
}


// ---------------------------------------------------------------------------
// AVL height metadata helpers. These helpers read the stored height fields
// directly and apply the same source `ht`, `max`, and `plus` equations without
// cloning both height values at each comparison/construction.
// ---------------------------------------------------------------------------

/// Source height check `ht left = ht right + nat_of_num (Bit0 One)`.
#[inline]
fn height_eq_plus_two<A>(left: &Tree<A>, right: &Tree<A>) -> bool {
    match (left, right) {
        (Tree::Leaf, _) => false,
        (Tree::Node(_, (_, hl), _), Tree::Leaf) => nat_equal(hl, &nat_two()),
        (Tree::Node(_, (_, hl), _), Tree::Node(_, (_, hr), _)) => {
            let rhs = nat_plus(hr.clone(), nat_two());
            nat_equal(hl, &rhs)
        }
    }
}

/// Source height comparison `ht left <= ht right`.
#[inline]
fn height_le<A>(left: &Tree<A>, right: &Tree<A>) -> bool {
    match (left, right) {
        (Tree::Leaf, _) => true,
        (Tree::Node(_, (_, hl), _), Tree::Leaf) => nat_less_eq(hl, &Nat::zero()),
        (Tree::Node(_, (_, hl), _), Tree::Node(_, (_, hr), _)) => nat_less_eq(hl, hr),
    }
}

/// Source `node` height `max (ht l) (ht r) + 1`, evaluated from the stored
/// height fields without materializing redundant `Nat` clones.
#[inline]
fn node_height<A>(left: &Tree<A>, right: &Tree<A>) -> Nat {
    match (left, right) {
        (Tree::Leaf, Tree::Leaf) => nat_one(),
        (Tree::Leaf, Tree::Node(_, (_, hr), _)) => nat_plus(hr.clone(), nat_one()),
        (Tree::Node(_, (_, hl), _), Tree::Leaf) => nat_plus(hl.clone(), nat_one()),
        (Tree::Node(_, (_, hl), _), Tree::Node(_, (_, hr), _)) => {
            if nat_less_eq(hl, hr) {
                nat_plus(hr.clone(), nat_one())
            } else {
                nat_plus(hl.clone(), nat_one())
            }
        }
    }
}

/// Source `AVL_Set_Code_Test.ht`: read the stored height of a tree.
#[inline]
pub fn ht<A>(t: &Tree<A>) -> Nat {
    match t {
        Tree::Leaf => nat_zero(),
        Tree::Node(_, (_, n), _) => n.clone(),
    }
}

/// Source `AVL_Set_Code_Test.node`: construct a node with stored height
/// `max(ht l, ht r) + 1`.
#[inline]
pub fn node<A>(l: Tree<A>, a: A, r: Tree<A>) -> Tree<A> {
    let h = node_height(&l, &r);
    Tree::Node(Box::new(l), (a, h), Box::new(r))
}

/// Source `AVL_Set_Code_Test.balL`: source left rebalancing equation.
pub fn balL<A>(ab: Tree<A>, ca: A, c: Tree<A>) -> Tree<A> {
    if height_eq_plus_two(&ab, &c) {
        match ab {
            Tree::Node(a_box, (a, _x), b_box) => {
                let a_tree = *a_box;
                let b_tree = *b_box;
                if height_le(&b_tree, &a_tree) {
                    node(a_tree, a, node(b_tree, ca, c))
                } else {
                    match b_tree {
                        Tree::Node(b1_box, (b, _x), b2_box) => {
                            let b1 = *b1_box;
                            let b2 = *b2_box;
                            node(node(a_tree, a, b1), b, node(b2, ca, c))
                        }
                        Tree::Leaf => hol_undefined::<Tree<A>>(),
                    }
                }
            }
            Tree::Leaf => hol_undefined::<Tree<A>>(),
        }
    } else {
        node(ab, ca, c)
    }
}

/// Source `AVL_Set_Code_Test.balR`: source right rebalancing equation.
pub fn balR<A>(aa: Tree<A>, a: A, bc: Tree<A>) -> Tree<A> {
    if height_eq_plus_two(&bc, &aa) {
        match bc {
            Tree::Node(b_box, (c, _x), c_tree_box) => {
                let b_tree = *b_box;
                let c_tree = *c_tree_box;
                if height_le(&b_tree, &c_tree) {
                    node(node(aa, a, b_tree), c, c_tree)
                } else {
                    match b_tree {
                        Tree::Node(b1_box, (b, _x), b2_box) => {
                            let b1 = *b1_box;
                            let b2 = *b2_box;
                            node(node(aa, a, b1), b, node(b2, c, c_tree))
                        }
                        Tree::Leaf => hol_undefined::<Tree<A>>(),
                    }
                }
            }
            Tree::Leaf => hol_undefined::<Tree<A>>(),
        }
    } else {
        node(aa, a, bc)
    }
}

/// Source `AVL_Set_Code_Test.split_max`: remove and return the maximum
/// element, together with the residual tree.
pub fn split_max<A: Ord>(t: Tree<A>) -> (Tree<A>, A) {
    match t {
        Tree::Leaf => hol_undefined::<(Tree<A>, A)>(),
        Tree::Node(l_box, (a, _n), r_box) => {
            let l = *l_box;
            let r = *r_box;
            if equal_tree(&r, &Tree::Leaf) {
                (l, a)
            } else {
                let (r2, y) = split_max(r);
                (balL(l, a, r2), y)
            }
        }
    }
}

/// Source `AVL_Set_Code_Test.insert`: insert with the exact source dispatch
/// on `cmp x a`, rebalancing only the LT and GT branches.
pub fn insert<A: Ord>(x: A, t: Tree<A>) -> Tree<A> {
    match t {
        Tree::Leaf => Tree::Node(
            Box::new(Tree::Leaf),
            (x, nat_one()),
            Box::new(Tree::Leaf),
        ),
        Tree::Node(l_box, (a, n), r_box) => match cmp(&x, &a) {
            CmpVal::LT => {
                let l = *l_box;
                let r = *r_box;
                balL(insert(x, l), a, r)
            }
            CmpVal::EQ => Tree::Node(l_box, (a, n), r_box),
            CmpVal::GT => {
                let l = *l_box;
                let r = *r_box;
                balR(l, a, insert(x, r))
            }
        },
    }
}

/// Source `AVL_Set_Code_Test.delete`: delete with the exact source dispatch
/// on `cmp x a` and the source split_max/equal_tree treatment of EQ.
pub fn delete<A: Ord>(x: A, t: Tree<A>) -> Tree<A> {
    match t {
        Tree::Leaf => Tree::Leaf,
        Tree::Node(l_box, (a, _n), r_box) => match cmp(&x, &a) {
            CmpVal::LT => {
                let l = *l_box;
                let r = *r_box;
                balR(delete(x, l), a, r)
            }
            CmpVal::EQ => {
                let l = *l_box;
                let r = *r_box;
                if equal_tree(&l, &Tree::Leaf) {
                    r
                } else {
                    let (l2, a2) = split_max(l);
                    balR(l2, a2, r)
                }
            }
            CmpVal::GT => {
                let l = *l_box;
                let r = *r_box;
                balL(l, a, delete(x, r))
            }
        },
    }
}

