#[inline]
pub fn hol_if<A, ThenBranch, ElseBranch>(condition: bool, then_branch: ThenBranch, else_branch: ElseBranch) -> A
where
    ThenBranch: FnOnce() -> A,
    ElseBranch: FnOnce() -> A,
