pub type Num = Nat;

#[inline]
pub fn nat_zero() -> Nat { Nat::zero() }

#[inline]
pub fn nat_suc(n: Nat) -> Nat { n + Nat::one() }

#[inline]
pub fn nat_one() -> Nat { Nat::one() }

