#[inline]
pub fn nat_of_num(n: Num) -> Nat { n }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmpVal { LT, EQ, GT }

#[inline]
pub fn cmp<A: Ord>(x: &A, y: &A) -> CmpVal {
    if x < y { CmpVal::LT } else if x == y { CmpVal::EQ } else { CmpVal::GT }
}

#[inline]
pub fn case_cmp_val<A, F1, F2, F3>(f1: F1, f2: F2, f3: F3, v: CmpVal) -> A
where
    F1: FnOnce() -> A,
    F2: FnOnce() -> A,
    F3: FnOnce() -> A,
{
    match v {
        CmpVal::LT => f1(),
        CmpVal::EQ => f2(),
        CmpVal::GT => f3(),
    }
}

#[inline]
pub fn ord_max<A: PartialOrd>(a: A, b: A) -> A {
    if a <= b { b } else { a }
}

#[inline]
fn nat_two() -> Nat { Nat::from(2u8) }

#[inline]
fn height_eq_value<A>(t: &Tree<A>, h: &Nat) -> bool {
    match t {
        Tree::Leaf => h.is_zero(),
        Tree::Node(_, (_, n), _) => nat_equal(n, h),
    }
}

#[inline]
fn height_le<A>(l: &Tree<A>, r: &Tree<A>) -> bool {
    match (l, r) {
        (Tree::Leaf, _) => true,
        (Tree::Node(_, (_, a), _), Tree::Leaf) => a.is_zero(),
        (Tree::Node(_, (_, a), _), Tree::Node(_, (_, b), _)) => nat_less_eq(a, b),
    }
}

#[inline]
fn height_plus_two<A>(t: &Tree<A>) -> Nat {
    match t {
        Tree::Leaf => nat_two(),
        Tree::Node(_, (_, n), _) => nat_plus(n.clone(), nat_two()),
    }
}

#[inline]
fn node_height<A>(l: &Tree<A>, r: &Tree<A>) -> Nat {
    let m = match (l, r) {
        (Tree::Leaf, Tree::Leaf) => nat_zero(),
        (Tree::Leaf, Tree::Node(_, (_, hr), _)) => hr.clone(),
        (Tree::Node(_, (_, hl), _), Tree::Leaf) => hl.clone(),
        (Tree::Node(_, (_, hl), _), Tree::Node(_, (_, hr), _)) => {
            if nat_less_eq(hl, hr) { hr.clone() } else { hl.clone() }
        }
    };
    nat_plus(m, nat_one())
}

#[inline]
fn node_boxed<A>(l: Box<Tree<A>>, a: A, r: Box<Tree<A>>) -> Tree<A> {
    let h = node_height(&*l, &*r);
    Tree::Node(l, (a, h), r)
}

#[inline]
pub fn ht<A>(t: &Tree<A>) -> Nat {
    match t {
        Tree::Leaf => nat_zero(),
        Tree::Node(_, (_, n), _) => n.clone(),
    }
}

#[inline]
pub fn node<A>(l: Tree<A>, a: A, r: Tree<A>) -> Tree<A> {
    node_boxed(Box::new(l), a, Box::new(r))
}

fn balL_boxed<A>(ab: Box<Tree<A>>, ca: A, c: Box<Tree<A>>) -> Tree<A> {
    if height_eq_value(&*ab, &height_plus_two(&*c)) {
        match *ab {
            Tree::Node(a_box, (a, _x), b_box) => {
                if height_le(&*b_box, &*a_box) {
                    let inner = node_boxed(b_box, ca, c);
                    node_boxed(a_box, a, Box::new(inner))
                } else {
                    match *b_box {
                        Tree::Node(b1_box, (b, _x), b2_box) => {
                            let left = node_boxed(a_box, a, b1_box);
                            let right = node_boxed(b2_box, ca, c);
                            node_boxed(Box::new(left), b, Box::new(right))
                        }
                        Tree::Leaf => hol_undefined::<Tree<A>>(),
                    }
                }
            }
            Tree::Leaf => hol_undefined::<Tree<A>>(),
        }
    } else {
        node_boxed(ab, ca, c)
    }
}

pub fn balL<A>(ab: Tree<A>, ca: A, c: Tree<A>) -> Tree<A> {
    balL_boxed(Box::new(ab), ca, Box::new(c))
}

fn balR_boxed<A>(aa: Box<Tree<A>>, a: A, bc: Box<Tree<A>>) -> Tree<A> {
    if height_eq_value(&*bc, &height_plus_two(&*aa)) {
        match *bc {
            Tree::Node(b_box, (c, _x), c_tree_box) => {
                if height_le(&*b_box, &*c_tree_box) {
                    let inner = node_boxed(aa, a, b_box);
                    node_boxed(Box::new(inner), c, c_tree_box)
                } else {
                    match *b_box {
                        Tree::Node(b1_box, (b, _x), b2_box) => {
                            let left = node_boxed(aa, a, b1_box);
                            let right = node_boxed(b2_box, c, c_tree_box);
                            node_boxed(Box::new(left), b, Box::new(right))
                        }
                        Tree::Leaf => hol_undefined::<Tree<A>>(),
                    }
                }
            }
            Tree::Leaf => hol_undefined::<Tree<A>>(),
        }
    } else {
        node_boxed(aa, a, bc)
    }
}

pub fn balR<A>(aa: Tree<A>, a: A, bc: Tree<A>) -> Tree<A> {
    balR_boxed(Box::new(aa), a, Box::new(bc))
}

pub fn split_max<A: Ord>(t: Tree<A>) -> (Tree<A>, A) {
    match t {
        Tree::Leaf => hol_undefined::<(Tree<A>, A)>(),
        Tree::Node(l_box, (a, _n), r_box) => {
            if matches!(&*r_box, Tree::Leaf) {
                (*l_box, a)
            } else {
                let (r2, y) = split_max(*r_box);
                (balL_boxed(l_box, a, Box::new(r2)), y)
            }
        }
    }
}

pub fn insert<A: Ord>(x: A, t: Tree<A>) -> Tree<A> {
    match t {
        Tree::Leaf => Tree::Node(Box::new(Tree::Leaf), (x, nat_one()), Box::new(Tree::Leaf)),
        Tree::Node(l_box, (a, n), r_box) => match cmp(&x, &a) {
            CmpVal::LT => balL_boxed(Box::new(insert(x, *l_box)), a, r_box),
            CmpVal::EQ => Tree::Node(l_box, (a, n), r_box),
            CmpVal::GT => balR_boxed(l_box, a, Box::new(insert(x, *r_box))),
        },
    }
}

pub fn delete<A: Ord>(x: A, t: Tree<A>) -> Tree<A> {
    match t {
        Tree::Leaf => Tree::Leaf,
        Tree::Node(l_box, (a, _n), r_box) => match cmp(&x, &a) {
            CmpVal::LT => balR_boxed(Box::new(delete(x, *l_box)), a, r_box),
            CmpVal::EQ => {
                if matches!(&*l_box, Tree::Leaf) {
                    *r_box
                } else {
                    let (l2, a2) = split_max(*l_box);
                    balR_boxed(Box::new(l2), a2, r_box)
                }
            }
            CmpVal::GT => balL_boxed(l_box, a, Box::new(delete(x, *r_box))),
        },
    }
}

//! Eratosthenes sieve over mathematical naturals.

pub type Nat = i2r_numeric::Nat;

pub fn zero_nat() -> Nat { Nat::zero() }
pub fn suc(n: Nat) -> Nat { n + Nat::one() }
pub fn one_nat() -> Nat { suc(zero_nat()) }
pub fn minus_nat(m: Nat, n: Nat) -> Nat { m.sub_trunc(&n) }

pub type Option<T> = std::option::Option<T>;
pub fn none<T>() -> Option<T> { std::option::Option::None }
pub fn some<T>(x: T) -> Option<T> { std::option::Option::Some(x) }

pub type Prod<A, B> = (A, B);
pub fn pair<A, B>(a: A, b: B) -> Prod<A, B> { (a, b) }
pub fn fst<A, B>(p: Prod<A, B>) -> A { p.0 }
pub fn snd<A, B>(p: Prod<A, B>) -> B { p.1 }

pub type Bool = bool;
pub const TRUE: Bool = true;
pub const FALSE: Bool = false;
pub fn if_then_else<T, F, G>(cond: Bool, then_branch: F, else_branch: G) -> T
where
    F: FnOnce() -> T,
    G: FnOnce() -> T,
{
    if cond { then_branch() } else { else_branch() }
}

pub type List<T> = Vec<T>;
pub fn nil<T>() -> List<T> { Vec::new() }
pub fn cons<T>(x: T, xs: List<T>) -> List<T> {
    let mut result = Vec::new();
    result.push(x);
    result.extend(xs);
    result
}
pub fn enumerate<T>(n: Nat, xs: List<T>) -> List<Prod<Nat, T>> {
    let capacity = xs.len();
    let mut result = Vec::with_capacity(capacity);
    let mut index = n;
    let one = Nat::one();
    for x in xs {
        let current = index.clone();
        result.push((current, x));
        index += &one;
    }
    result
}
pub fn replicate<T: Clone>(n: &Nat, x: T) -> List<T> {
    let count = match n.try_to_usize() {
        Ok(count) => count,
        Err(_) => panic!("replicate count exceeds resident container length"),
    };
    let mut result = Vec::with_capacity(count);
    let mut i = 0usize;
    while i < count {
        result.push(x.clone());
        i += 1;
    }
    result
}
pub fn map_filter<A, B, F>(f: F, xs: List<A>) -> List<B>
where
    F: FnMut(A) -> Option<B>,
{
    let mut f = f;
    let mut result = Vec::with_capacity(xs.len());
    for x in xs {
        match f(x) {
            None => {}
            Some(y) => result.push(y),
        }
    }
    result
}

#[derive(Clone, Debug)]
pub enum Num {
    One,
    Bit0(Box<Num>),
    Bit1(Box<Num>),
}
pub fn num_one() -> Num { Num::One }
pub fn num_bit0(n: Num) -> Num { Num::Bit0(Box::new(n)) }
pub fn nat_of_num(n: Num) -> Nat {
    match n {
        Num::One => one_nat(),
        Num::Bit0(inner) => {
            let m = nat_of_num(*inner);
            m.clone() + m
        }
        Num::Bit1(inner) => {
            let m = nat_of_num(*inner);
            suc(m.clone() + m)
        }
    }
}

/// Exact Nat realization of one left-to-right countdown pass:
/// nonzero countdown keeps the cell and takes the predecessor, zero countdown
/// writes FALSE and resets the countdown to `n`.
fn mark_out_slice_nat(n: &Nat, mut m: Nat, bs: &mut [Bool]) {
    let one = Nat::one();
    for b in bs.iter_mut() {
        if m.is_zero() {
            *b = FALSE;
            m = n.clone();
        } else {
            m = m.sub_trunc(&one);
        }
    }
}

/// Machine-carrier realization of the same countdown pass. `n_usize`/`m` are
/// exact images of the source naturals (established by the caller's exact
/// conversion), so each cell performs the same zero/nonzero decision, the same
/// FALSE write with reset, and the same predecessor step; the decrement is
/// guarded by `m != 0`.
fn mark_countdown(n_usize: usize, mut m: usize, bs: &mut [Bool]) {
    for b in bs.iter_mut() {
        if m == 0 {
            *b = FALSE;
            m = n_usize;
        } else {
            m -= 1;
        }
    }
}

/// Exact Nat realization of sieve: one successor step per flag, tail marking on
/// a TRUE head with the current index as both reset value and countdown start.
fn sieve_nat(n: &Nat, one: &Nat, bs: &mut [Bool]) {
    let mut current = n.clone();
    let len = bs.len();
    let mut pos = 0usize;
    while pos < len {
        let b = bs[pos];
        pos += 1;
        if b && pos < len {
            mark_out_slice_nat(&current, current.clone(), &mut bs[pos..]);
        }
        current += one;
    }
}

pub fn mark_out(n: &Nat, mut bs: List<Bool>) -> List<Bool> {
    if !bs.is_empty() {
        match n.try_to_usize() {
            Ok(n_usize) => mark_countdown(n_usize, n_usize, &mut bs),
            Err(_) => mark_out_slice_nat(n, n.clone(), &mut bs),
        }
    }
    bs
}

pub fn mark_out_aux(n: &Nat, m: Nat, mut bs: List<Bool>) -> List<Bool> {
    if !bs.is_empty() {
        let n_usize = n.try_to_usize().ok();
        let m_usize = m.try_to_usize().ok();
        match (n_usize, m_usize) {
            (Some(n_usize), Some(m_usize)) => mark_countdown(n_usize, m_usize, &mut bs),
            _ => mark_out_slice_nat(n, m, &mut bs),
        }
    }
    bs
}

pub fn sieve(n: &Nat, mut bs: List<Bool>) -> List<Bool> {
    let len = bs.len();
    if len == 0 {
        return bs;
    }
    match n.try_to_usize() {
        // The sieve index is internal (it never escapes) and `len` cells mean at
        // most `len` successor steps, so `start + len` representable in usize
        // makes every index value an exact image of the source natural.
        Ok(start) => match start.checked_add(len) {
            Some(_) => {
                let mut index = start;
                let mut pos = 0usize;
                while pos < len {
                    let b = bs[pos];
                    pos += 1;
                    if b && pos < len {
                        mark_countdown(index, index, &mut bs[pos..]);
                    }
                    index += 1;
                }
            }
            None => {
                let one = Nat::one();
                sieve_nat(n, &one, &mut bs);
            }
        },
        Err(_) => {
            let one = Nat::one();
            sieve_nat(n, &one, &mut bs);
        }
    }
    bs
}

pub fn primes_upto(n: &Nat) -> List<Nat> {
    let start = nat_of_num(num_bit0(num_one()));
    let count = minus_nat(n.clone(), one_nat());
    let flags = replicate(&count, TRUE);
    let sieved = sieve(&one_nat(), flags);
    // Storage fusion of the source route
    //   map_filter (if snd x then Some (fst x) else None) (enumerate start sieved)
    // into one forward pass: cell `i` still constructs the same pair
    // (index_i, flag_i), the callback below is applied exactly once to that cell
    // head-to-tail, the case split drops None and pushes the same fst value for
    // Some, and exactly one successor step is taken per input cell (including the
    // discarded successor after the last cell). Only the intermediate Vec of
    // already-computed (index, flag) pairs is not materialized.
    let capacity = sieved.len();
    let mut result = Vec::with_capacity(capacity);
    let mut index = start;
    let one = Nat::one();
    for flag in sieved {
        let current = index.clone();
        let cell: Prod<Nat, Bool> = pair(current, flag);
        let outcome: Option<Nat> = {
            let (idx, keep) = cell;
            if keep { some(idx) } else { none() }
        };
        match outcome {
            None => {}
            Some(y) => result.push(y),
        }
        index += &one;
    }
    result
}

