///   `mark_out_aux n m [] = []`.
///
/// The marking result has exactly the length of the visited cell sequence and
/// its i-th element depends only on the i-th input flag and on the countdown
/// state.  The same cells are therefore visited once, in the same order, with
/// the same per-cell decision (keep the flag while the countdown is nonzero,
/// emit `False` and reset to `n` when it is zero), and the computed value is
/// stored back into the owned buffer instead of into a freshly built spine.  The
/// countdown uses the source predecessor (`minus_nat m 1`) on the nonzero branch
/// only; the constant one of that step is passed in prepared instead of being
/// rebuilt for every cell.
fn mark_out_aux_into(n: &Nat, mut m: Nat, bs: &mut [bool], one: &Nat) {
    for slot in bs.iter_mut() {
        if m.is_zero() {
            *slot = FALSE;
            m = n.clone();
        } else {
            m = m.sub_trunc(one);
        }
    }
}

/// `Eratosthenes.mark_out_aux`.
///
/// Signature and source equations unchanged; the traversal is realized in
/// place on the consumed flag buffer (see `mark_out_aux_into`).
pub fn mark_out_aux(n: &Nat, m: Nat, bs: List<Bool>) -> List<Bool> {
    let mut bs = bs;
    let one = one_nat();
    mark_out_aux_into(n, m, &mut bs, &one);
    bs
}

/// `Eratosthenes.sieve`.
///
/// Source equations:
///   `sieve n [] = []`,
///   `sieve n (False # bs) = False # sieve (Suc n) bs`,
///   `sieve n (True # bs) = True # sieve (Suc n) (mark_out n bs)`.
///
/// One left-to-right pass over the owned flag buffer: the cell at the current
/// position keeps exactly the value the source emits for that head flag, a
/// `True` head first marks out the remaining tail with `mark_out n tail` (the
/// same per-cell transitions, in the same order, performed in place on that
/// tail), and only then does the index advance by `Suc n` to the next position.
pub fn sieve(n: &Nat, bs: List<Bool>) -> List<Bool> {
    let mut n = n.clone();
    let mut bs = bs;
    let one = one_nat();
    let mut i = 0usize;
    while i < bs.len() {
        if bs[i] {
            let (_, tail) = bs.split_at_mut(i + 1);
            mark_out_aux_into(&n, n.clone(), tail, &one);
        }
        n = n + one.clone();
        i += 1;
    }
    bs
}

/// `Eratosthenes.primes_upto`.
///
/// Source equation:
/// `primes_upto n = map_filter (\<lambda>x. if snd x then Some (fst x) else None)
///    (enumerate (nat_of_num (Bit0 One))
///       (sieve one_nat (replicate (n - 1) True)))`.
pub fn primes_upto(n: &Nat) -> List<Nat> {
    let start = nat_of_num(num_bit0(num_one()));
    let count = minus_nat(n.clone(), one_nat());
    let flags = replicate(&count, TRUE);
    let sieved = sieve(&one_nat(), flags);
    let indexed = enumerate(start, sieved);
    map_filter(
        |x: Prod<Nat, Bool>| {
            let (idx, flag) = x;
            if flag {
                some(idx)
            } else {
                none()
            }
        },
        indexed,
    )
}

