}

/// The source type `List.list`.
pub type List<T> = Vec<T>;

/// `List.list.Nil`.
pub fn nil<T>() -> List<T> {
    Vec::new()
}

/// `List.list.Cons`.
pub fn cons<T>(x: T, xs: List<T>) -> List<T> {
    let mut result = Vec::with_capacity(xs.len() + 1);
    result.push(x);
    result.extend(xs);
    result
}

/// `List.enumerate`.
///
/// Equations: `enumerate n [] = []`,
/// `enumerate n (x # xs) = (n, x) # enumerate (Suc n) xs`.
/// One source successor addition per element, in source order; the constant one
/// of that step is prepared once instead of being rebuilt per element, and the
/// accumulator is borrowed rather than cloned (the produced value is
/// unchanged), so no closed-form index arithmetic replaces the recurrence.
pub fn enumerate<T>(n: Nat, xs: List<T>) -> List<Prod<Nat, T>> {
    let one = one_nat();
    let mut result = Vec::with_capacity(xs.len());
    let mut index = n;
    for x in xs {
        let next = &index + &one;
        result.push((index, x));
        index = next;
    }
    result
}

/// `List.replicate`.
pub fn replicate<T: Clone>(n: &Nat, x: T) -> List<T> {
    let count = match n.try_to_usize() {
        Ok(count) => count,
        Err(_) => panic!("replicate count exceeds resident container length"),
    };
    let mut result = Vec::with_capacity(count);
    let mut i = 0usize;
    while i < count {
        result.push(x.clone());
        i += 1;
    }
    result
}

/// `List.map_filter`.
pub fn map_filter<A, B, F>(f: F, xs: List<A>) -> List<B>
where
    F: FnMut(A) -> Option<B>,
{
    let mut f = f;
    let mut result = Vec::new();
    for x in xs {
        match f(x) {
            None => {}
            Some(y) => result.push(y),
        }
    }
    result
}

/// The source type `Num.num`: binary numerals `One`, `Bit0`, `Bit1`.
#[derive(Clone, Debug)]
pub enum Num {
    One,
    Bit0(Box<Num>),
    Bit1(Box<Num>),
}

/// `Num.num.One`.
pub fn num_one() -> Num {
    Num::One
}

/// `Num.num.Bit0`.
pub fn num_bit0(n: Num) -> Num {
    Num::Bit0(Box::new(n))
}

/// `Num.nat_of_num`.
///
/// Source equations:
/// `nat_of_num One = 1`,
/// `nat_of_num (Bit0 n) = let m = nat_of_num n in m + m`,
/// `nat_of_num (Bit1 n) = let m = nat_of_num n in Suc (m + m)`.
/// The single bound `m` is used for both summands; it is borrowed for the one
/// doubling addition instead of being cloned, which keeps exactly one addition
/// (plus the source successor for `Bit1`) per constructor.
pub fn nat_of_num(n: Num) -> Nat {
    match n {
        Num::One => one_nat(),
        Num::Bit0(inner) => {
            let m = nat_of_num(*inner);
            &m + &m
        }
        Num::Bit1(inner) => {
            let m = nat_of_num(*inner);
            suc(&m + &m)
        }
    }
}

/// `Eratosthenes.mark_out`.
///
/// Source equation: `mark_out n bs = mark_out_aux n n bs`.
/// `n` serves as both the reset value and the initial countdown, so the owned
/// countdown copy is not materialized before the traversal.
pub fn mark_out(n: &Nat, bs: List<Bool>) -> List<Bool> {
    let mut bs = bs;
    let one = one_nat();
    mark_out_aux_into(n, n, &mut bs, &one);
    bs
}

/// Storage realization of the `Eratosthenes.mark_out_aux` transitions when
/// both the reset value and the initial countdown are already exact `usize`
/// values.  This is the shared machine-carrier path used by the guarded
/// conversion in `mark_out_aux_into` and directly by `sieve`'s guarded index
/// loop.  It performs exactly one countdown transition per visited cell:
/// nonzero keeps the flag and decrements, zero writes `FALSE` and resets to the
/// exact `usize` reset value.
fn mark_out_aux_into_usize(reset: usize, start: usize, bs: &mut [bool]) {
    let mut countdown = start;
    for slot in bs.iter_mut() {
        if countdown == 0 {
            *slot = FALSE;
            countdown = reset;
        } else {
            countdown -= 1;
        }
    }
}

/// Storage realization of the `Eratosthenes.mark_out_aux` transitions.
///
/// Source equations (left to right, exactly one transition per visited cell):
///   `mark_out_aux n (Suc m) (b # bs) = b # mark_out_aux n m bs`,
///   `mark_out_aux n 0 (b # bs) = False # mark_out_aux n n bs`,
///   `mark_out_aux n m [] = []`.
///
/// The result has the same length as the visited cell sequence and its i-th
/// value is determined by the i-th input flag and the countdown state alone, so
/// storing the computed value back into the owned buffer encodes exactly the
/// same visits, in the same order, with the same per-cell decision (keep the
/// flag while the countdown is nonzero; write `False` and reset to `n` when it
/// is zero) as building a fresh spine.
///
/// The countdown state is derived from the two source arguments alone: after the
/// first reset every value is `<= n`, and before it every value is `<= m`, so on
/// the path where `n` and `m` both convert exactly with `Nat::try_to_usize` the
/// same mathematical countdown is carried in `usize`, with one guarded
/// decrement per nonzero step (no value below zero can arise) and the reset to
/// `n`.  Every other input takes the exact `Nat` loop (`is_zero` /
/// `sub_trunc(&one)` / `n.clone()`), so no machine bound is assumed for any
/// value: the conversion is the guard and the fallback is complete.
fn mark_out_aux_into(n: &Nat, m: &Nat, bs: &mut [bool], one: &Nat) {
    if let (Ok(reset), Ok(start)) = (n.try_to_usize(), m.try_to_usize()) {
        mark_out_aux_into_usize(reset, start, bs);
        return;
    }
    let mut countdown = m.clone();
    for slot in bs.iter_mut() {
        if countdown.is_zero() {
            *slot = FALSE;
            countdown = n.clone();
        } else {
            countdown = countdown.sub_trunc(one);
        }
    }
}

/// `Eratosthenes.mark_out_aux`.
///
/// Signature and source equations unchanged; the traversal is realized in place
/// on the consumed flag buffer (see `mark_out_aux_into`).
pub fn mark_out_aux(n: &Nat, m: Nat, bs: List<Bool>) -> List<Bool> {
    let mut bs = bs;
    let one = one_nat();
    mark_out_aux_into(n, &m, &mut bs, &one);
    bs
}

/// `Eratosthenes.sieve`.
///
/// Source equations:
///   `sieve n [] = []`,
///   `sieve n (False # bs) = False # sieve (Suc n) bs`,
///   `sieve n (True # bs) = True # sieve (Suc n) (mark_out n bs)`.
///
/// One positional left-to-right pass over the owned flag buffer: the current
/// cell already holds exactly the flag the source emits for that head, a `True`
/// head first marks out the remaining tail, i.e. positions `i + 1 ..` (exactly
/// the tail list handed to `mark_out` in the source), and only then does the
/// index advance by `Suc n`.  Earlier positions are never touched again, so the
/// retained prefix is exactly the source-emitted prefix.  The constant one of
/// the successor step is prepared once and the accumulator is borrowed, so one
/// successor addition still happens per visited position in the exact path.
///
/// When the source index `n` converts exactly with `Nat::try_to_usize` and the
/// whole pass's largest index `start + length` fits in `usize`, the same index
/// sequence is carried in `usize`: one increment per visited position, the exact
/// current index passed as both reset value and initial countdown to the shared
/// machine helper for a `TRUE` head, and no position skipped, strided over or
/// revisited.  Every other input takes the exact `Nat` loop below, so no machine
/// bound is assumed for any source input.
pub fn sieve(n: &Nat, bs: List<Bool>) -> List<Bool> {
    let mut bs = bs;
    let len = bs.len();
    let mut i = 0usize;
    if let Ok(start) = n.try_to_usize() {
        if start.checked_add(len).is_some() {
            let mut current = start;
            while i < len {
                if bs[i] {
                    let (_, tail) = bs.split_at_mut(i + 1);
                    mark_out_aux_into_usize(current, current, tail);
                }
                current += 1;
                i += 1;
            }
            return bs;
        }
    }
    let one = one_nat();
    let mut n = n.clone();
    while i < len {
        if bs[i] {
            let (_, tail) = bs.split_at_mut(i + 1);
            mark_out_aux_into(&n, &n, tail, &one);
        }
        let next = &n + &one;
        n = next;
        i += 1;
    }
    bs
}

/// `Eratosthenes.primes_upto`.
///
/// Source equation:
/// `primes_upto n = map_filter (if snd x then Some (fst x) else None)
///    (enumerate (nat_of_num (Bit0 One))
///       (sieve one_nat (replicate (n - 1) True)))`.
///
/// The sieving stage is realized as in `sieve`.  The final `enumerate` followed
/// by `map_filter` is a pure producer/consumer pair over the already-computed
/// flag list: every sieved flag is enumerated once in source order, the index
/// starts at `nat_of_num (Bit0 One)` and advances by exactly one successor
/// addition per flag, and the filter emits the current index exactly when that
/// flag is `TRUE`.  Fusing that storage pair removes the intermediate list of
/// `(index, flag)` pairs without skipping an enumeration position, reordering a
/// callback decision, or changing the emitted index sequence.  The public
/// `enumerate` and `map_filter` helpers remain available unchanged.
pub fn primes_upto(n: &Nat) -> List<Nat> {
    let start = nat_of_num(num_bit0(num_one()));
    let count = minus_nat(n.clone(), one_nat());
    let flags = replicate(&count, TRUE);
    let sieved = sieve(&one_nat(), flags);
    let one = one_nat();
    let mut index = start;
    let mut result = Vec::new();
    for flag in sieved {
        let next = &index + &one;
        if flag {
            result.push(index);
        }
        index = next;
    }
    result
}

