/// `Node`.  The two rank lookups and the mathematical comparison are the ones
/// the source `node` equation performs; only the owned copy of a rank that the
/// caller merely reads is not materialized.
fn mht_ref<A>(t: &Tree<(A, Nat)>) -> Option<&Nat> {
    match t {
        Tree::Leaf => None,
        Tree::Node(_, (_, n), _) => Some(n),
    }
}

