///
/// `None` denotes the source zero, so this is the exact mathematical
/// comparison of the two ranks, including a node whose stored rank happens to
/// be zero.
fn rank_le(rr: Option<&Nat>, rl: Option<&Nat>) -> bool {
    match (rr, rl) {
        (None, _) => true,
        (Some(a), None) => a.is_zero(),
        (Some(a), Some(b)) => nat_le(a, b),
    }
}

/// Source `plus_nat_inst.plus_nat rr one_nat_inst.one_nat` for a borrowed rank
/// view: the selected rank is obtained exactly once from its subtree and then
/// incremented with the registered natural addition.
fn rank_succ(rank: Option<&Nat>) -> Nat {
    let base = match rank {
        None => zero_nat_inst_zero_nat(),
        Some(n) => n.clone(),
    };
    plus_nat_inst_plus_nat(base, one_nat_inst_one_nat())
}

/// Source `Leftist_Heap_Test.node` over boxed subtrees.
///
/// The source equation is preserved exactly: the two ranks are looked up, the
/// source branch test `rr <= rl` selects the layout, the selected rank is
/// incremented by one, and the else branch swaps left and right.  The only
/// difference from the spelled-out public `node` is that the child boxes are
/// taken by value and reused as the resulting node's recursive fields, so the
/// pure list-spine storage needs no fresh allocation.
fn node_boxed<A>(l: Box<Tree<(A, Nat)>>, a: A, r: Box<Tree<(A, Nat)>>) -> Tree<(A, Nat)> {
    let rl = mht_ref(&*l);
    let rr = mht_ref(&*r);
    if rank_le(rr, rl) {
        let rank = rank_succ(rr);
        Tree::Node(l, (a, rank), r)
    } else {
        let rank = rank_succ(rl);
        Tree::Node(r, (a, rank), l)
    }
}

