/// nullary `Leaf` placeholder behind.
///
/// This is pure list-spine storage: the box allocation is reused by the caller
/// for the already-computed merged subtree, so no business transition is added,
/// removed or reordered.
fn take_subtree<A>(b: &mut Box<Tree<(A, Nat)>>) -> Tree<(A, Nat)> {
    std::mem::replace(&mut **b, Tree::Leaf)
}

/// Source `Leftist_Heap_Test.merge`.
///
/// The three source equations and the source recursion route are unchanged: the
/// two-node case compares `a1 <= a2` and recurses on the source-selected right
/// spine with the other node reconstructed exactly as a source let-binding.  The
/// right-spine box is reused to carry the recursive result into the `node` call,
/// which is pure spine storage rather than an additional business transition.
pub fn merge<A: OrderingsOrd>(t1: Tree<(A, Nat)>, t2: Tree<(A, Nat)>) -> Tree<(A, Nat)> {
    match (t1, t2) {
        (Tree::Leaf, t) => t,
        (t, Tree::Leaf) => t,
        (Tree::Node(l1, (a1, n1), mut r1), Tree::Node(l2, (a2, n2), mut r2)) => {
            if ord_class_less_eq(&a1, &a2) {
                let t2 = Tree::Node(l2, (a2, n2), r2);
                let sub = take_subtree(&mut r1);
                let merged = merge(sub, t2);
                *r1 = merged;
                node_boxed(l1, a1, r1)
            } else {
                let t1 = Tree::Node(l1, (a1, n1), r1);
                let sub = take_subtree(&mut r2);
                let merged = merge(t1, sub);
                *r2 = merged;
                node_boxed(l2, a2, r2)
            }
        }
    }
}

