/// Source `Orderings.ord`: a type class supplying a non-strict ordering
/// capability over a generic element type.
///
/// The source class declares the parameters `less_eq` and `less` over a
/// generic `'a::Orderings.ord`.  Only `less_eq` occurs in the translated
/// program, so the trait exposes exactly that capability and keeps the
/// element type generic; the source class does not require `Eq`, `Clone` or
/// `Copy` supertraits, so none are added here.
pub trait OrderingsOrd {
    /// Source `Orderings.ord_class.less_eq` as a class parameter.
    fn less_eq(&self, other: &Self) -> bool;
}

/// Source `Orderings.ord_class.less_eq`: the polymorphic non-strict
/// comparison supplied by the `Orderings.ord` capability.
///
/// There are no default equations for an arbitrary type: the result is
/// exactly what the caller's `OrderingsOrd` instance defines for the two
/// arguments, and the generic parameter is never narrowed to `Nat` here.
#[inline]
pub fn ord_class_less_eq<A: OrderingsOrd>(a: &A, b: &A) -> bool {
    a.less_eq(b)
}


/// Source `Nat.ord_nat_inst.less_eq_nat`: the `Orderings.ord` instance's
/// non-strict comparison for mathematical naturals.
///
/// The source equations are `(Suc m <= n) = less_nat m n` and
/// `(0 <= n) = True`. These are exactly the ordinary mathematical order on
/// `i2r_numeric::Nat`, so the body must not use word/modular comparison or a
/// narrower integer representation.
#[inline]
pub fn nat_le(a: &Nat, b: &Nat) -> bool {
    a <= b
}

/// Source `Nat.ord_nat_inst.less_eq_nat` as the `Orderings.ord` instance
/// method for `Nat`.
impl OrderingsOrd for Nat {
    #[inline]
    fn less_eq(&self, other: &Self) -> bool {
        nat_le(self, other)
    }
}


/// Source `Leftist_Heap_Test.mht`.
///
/// Leaf yields source zero and a node yields exactly its stored rank; the rank
/// is cloned because `Nat` is never `Copy`.  The two equations are unchanged;
/// `#[inline]` only lets this two-arm stored-rank read fold into its caller.
#[inline]
pub fn mht<A>(t: &Tree<(A, Nat)>) -> Nat {
    match t {
        Tree::Leaf => zero_nat_inst_zero_nat(),
        Tree::Node(_, (_, n), _) => (*n).clone(),
    }
}

/// Source `Leftist_Heap_Test.node` transition with the left child supplied in
/// the `Box` it already occupies.
///
/// This performs exactly the source `node l a r` equation: read `rl = mht l`,
/// then `rr = mht r`, test `rr <= rl` (the source form `rl >= rr`), add one to
/// the source-selected rank with the registered natural-addition primitive, and
/// build the source-selected `Node` (`Node l (a, rr+1) r` in the first branch,
/// `Node r (a, rl+1) l` in the second).  The only difference from `node` is
/// representational: the left child arrives in the `Box` it already occupies,
/// so a caller that already owns that box does not unbox and re-box the
/// subtree.  No rank read, comparison, addition or constructor is added,
/// removed or reordered.
#[inline]
fn node_boxed_left<A>(l: Box<Tree<(A, Nat)>>, a: A, r: Tree<(A, Nat)>) -> Tree<(A, Nat)> {
    let rl = mht(&l);
    let rr = mht(&r);
    if nat_le(&rr, &rl) {
        let rank = plus_nat_inst_plus_nat(rr, one_nat_inst_one_nat());
        Tree::Node(l, (a, rank), Box::new(r))
    } else {
        let rank = plus_nat_inst_plus_nat(rl, one_nat_inst_one_nat());
        Tree::Node(Box::new(r), (a, rank), l)
    }
}

/// Source `Leftist_Heap_Test.node`.
#[inline]
pub fn node<A>(l: Tree<(A, Nat)>, a: A, r: Tree<(A, Nat)>) -> Tree<(A, Nat)> {
    node_boxed_left(Box::new(l), a, r)
}

/// Source `Leftist_Heap_Test.node` transition with BOTH children supplied in
/// the `Box`es they already occupy.
///
/// Same source transition as `node_boxed_left`: both rank inspections happen
/// before the `rr <= rl` test, the test is evaluated exactly once, one
/// registered natural addition by one is applied to the source-selected rank,
/// and the source-selected `Node` is constructed.  A Leaf contributes a fresh
/// zero exactly as `mht Leaf`; a Node contributes its stored rank by reference
/// for the comparison, so only the source-selected stored rank is cloned for
/// the single plus-one.  Neither child has to be (re)boxed, because the caller
/// already owns a `Box` for each side.
#[inline]
fn node_boxed<A>(
    l: Box<Tree<(A, Nat)>>,
    a: A,
    r: Box<Tree<(A, Nat)>>,
) -> Tree<(A, Nat)> {
    let (first, rank) = match (&*l, &*r) {
        (Tree::Leaf, Tree::Leaf) => {
            let rl = zero_nat_inst_zero_nat();
            let rr = zero_nat_inst_zero_nat();
            let first = nat_le(&rr, &rl);
            let rank = plus_nat_inst_plus_nat(rr, one_nat_inst_one_nat());
            (first, rank)
        }
        (Tree::Leaf, Tree::Node(_, (_, rn), _)) => {
            let rl = zero_nat_inst_zero_nat();
            let first = nat_le(rn, &rl);
            let rank = if first {
                plus_nat_inst_plus_nat((*rn).clone(), one_nat_inst_one_nat())
            } else {
                plus_nat_inst_plus_nat(rl, one_nat_inst_one_nat())
            };
            (first, rank)
        }
        (Tree::Node(_, (_, ln), _), Tree::Leaf) => {
            let rr = zero_nat_inst_zero_nat();
            let first = nat_le(&rr, ln);
            let rank = plus_nat_inst_plus_nat(rr, one_nat_inst_one_nat());
            (first, rank)
        }
        (Tree::Node(_, (_, ln), _), Tree::Node(_, (_, rn), _)) => {
            let first = nat_le(rn, ln);
            let rank = if first {
                plus_nat_inst_plus_nat((*rn).clone(), one_nat_inst_one_nat())
            } else {
                plus_nat_inst_plus_nat((*ln).clone(), one_nat_inst_one_nat())
            };
            (first, rank)
        }
    };
    if first {
        Tree::Node(l, (a, rank), r)
    } else {
        Tree::Node(r, (a, rank), l)
    }
}

/// Source `Leftist_Heap_Test.merge` recurrence, written into an already
/// allocated destination `Box` (`slot`).
///
/// This is the source merge recurrence itself, unchanged: a leaf argument
/// yields the other tree; two nodes compare `a1 <= a2` through the source
/// ordering capability and then perform the source-selected recursive merge of
/// the selected right subtree with the other node (rebuilt from its own
/// already owned boxes), wrapped in the source `node` transition applied to the
/// source-selected left child.
///
/// The `slot` is a purely representational out-parameter.  The caller hands
/// over the `Box` that previously held the source-selected descent subtree (its
/// content having been moved out with `mem::replace` by `Tree::Leaf`), so the
/// recursive result is stored in that existing allocation instead of being
/// returned unboxed and re-boxed by the enclosing `node` transition.  `slot`
/// therefore always contains `Tree::Leaf` on entry, which is what makes the
/// write a pure storage move.  No source rank read, comparison, addition,
/// constructor or recursive call is added, removed or reordered.
fn merge_into<A: OrderingsOrd>(
    t1: Tree<(A, Nat)>,
    t2: Tree<(A, Nat)>,
    mut slot: Box<Tree<(A, Nat)>>,
) -> Box<Tree<(A, Nat)>> {
    match (t1, t2) {
        (Tree::Leaf, t) => {
            *slot = t;
            slot
        }
        (t, Tree::Leaf) => {
            *slot = t;
            slot
        }
        (Tree::Node(l1, (a1, n1), mut r1), Tree::Node(l2, (a2, n2), mut r2)) => {
            if ord_class_less_eq(&a1, &a2) {
                let t2 = Tree::Node(l2, (a2, n2), r2);
                let sub = std::mem::replace(&mut *r1, Tree::Leaf);
                let merged = merge_into(sub, t2, r1);
                *slot = node_boxed(l1, a1, merged);
                slot
            } else {
                let t1 = Tree::Node(l1, (a1, n1), r1);
                let sub = std::mem::replace(&mut *r2, Tree::Leaf);
                let merged = merge_into(t1, sub, r2);
                *slot = node_boxed(l2, a2, merged);
                slot
            }
        }
    }
}

